 public void RestoreUtility(UtilitySave? data){if(data==null)return;ProbeFormation=data.Formation;ProbeLayoutCustomized=data.Customized;ProbeScanPass=data.ScanPass;ProbeSelection=data.Selection;ProbeJob=data.ScanJob;ProbePresets=data.Presets;Astrometrics=Math.Clamp(data.Astrometrics,1,5);AstrometricRangefinding=Math.Clamp(data.Rangefinding,0,5);AstrometricPinpointing=Math.Clamp(data.Pinpointing,0,5);AstrometricAcquisition=Math.Clamp(data.Acquisition,0,5);if(data.Rack.Length==16&&data.Rack.All(s=>s.ModuleId==""||UtilityCatalog.ById.ContainsKey(s.ModuleId)))Player.Utilities=data.Rack;UtilityStorage=data.Storage;CrystalConditions=data.Crystals;ScanProbes=data.Probes;UtilitySites=data.Sites;IndustrialCore=data.Core;CoreStop=data.CoreStop;CoreLeft=data.CoreLeft;ProbeScanLeft=data.ScanLeft;ProbeRange=float.IsFinite(data.ScanRange)?Math.Clamp(data.ScanRange,.25f,64):4;ProbeCenter=new(data.CenterX,data.CenterY,data.CenterZ);UtilityHackState=data.Hack;foreach(var td in data.Targets){var t=Targets.FirstOrDefault(t=>t.Id==td.Id);if(t==null&&Grid is "utility_range" or "utility_site"){t=new(){Id=td.Id,Name=td.SiteKind.Length>0?td.SiteKind:td.Resource+" resource",Kind=td.Kind,Position=new(td.X,td.Y,td.Z),Ore=td.Ore,Salvage=td.Salvage};Targets.Add(t);}if(t==null)continue;t.Resource=td.Resource;t.SiteKind=td.SiteKind;t.OwnerId=td.OwnerId;t.Contents=td.Contents;t.HackAttempts=td.Attempts;t.Hacked=td.Hacked;t.Destroyed=td.Destroyed;}}
