 public float UtilityRange(UtilityDefinition d)=>d.Range*Player.HarvestFactor(d,"range")*Player.HullFactor("utility","range",d.Analyzer?"Analyzer":d.Kind)*(d.Harvest?Player.SupportFactor("miningRange"):d.Analyzer?Player.SupportFactor("analyzerRange"):d.Kind=="Salvage"?Player.SupportFactor("salvageRange"):1);
 public string UtilityActivationError(UtilityState s){var d=s.Definition;if(d==null||!s.Effective)return "Online module required.";if(Cloaked)return "Decloak before using utilities.";if(Docked)return "Undock first.";if(d.Passive)return "Passive module.";if(s.ReloadLeft>0)return "Reloading.";if(d.Kind=="Compress")return IndustrialCore?"":"Deploy the industrial core first.";if(d.Kind is "CoreProbe" or "CombatProbe")return s.Loaded>0&&ScanProbes.Count(p=>p.System==SystemId)<8?"":"Load probes; maximum eight deployed.";var t=Locked;if(t==null)return "Lock a target first.";if(d.Range>0&&Vector3.Distance(Player.Position,t.Position)>UtilityRange(d)+(d.Kind=="ShipScan"?d.Falloff:0))return "Out of range.";if(d.Harvest){if(t.Kind!=TargetKind.Asteroid)return "Resource target required.";bool okay=d.Family=="Ice"?t.Resource=="ice":d.Family=="Gas"?t.Resource=="gas":t.Resource is "ore" or "moonore"||(t.Resource=="deepore"&&d.Kind.Contains("Deep"));if(!okay)return "Wrong resource for this harvester.";if(CargoRoom(t.Resource)<ItemVolume(t.Resource))return "Cargo full.";}
 if(d.Analyzer&&(t.Kind!=TargetKind.Container||t.Hacked||t.SiteKind is not ("Data" or "Relic")||d.Kind!="Integrated"&&d.Kind!=t.SiteKind))return "Matching unopened data/relic site required.";
 if(d.Kind=="Tractor"&&(t.Kind is not (TargetKind.Wreck or TargetKind.Container)||t.OwnerId!="player"))return "Owned wreck or container required.";if(d.Kind=="Salvage"&&(t.Kind!=TargetKind.Wreck||t.Salvage<=0))return "Recoverable wreck required.";if(d.Kind=="SurveyProbe"&&t.SiteKind=="Moon"&&Vector3.Dot(Player.Facing,Vector3.Normalize(t.Position-Player.Position))<.8f)return "Face the moon before launching the assay probe.";if(d.Kind=="SurveyProbe"&&(t.SiteKind!="Moon"||s.Loaded<1))return "Load a survey probe and lock a moon.";if(d.Kind=="Festival"&&s.Loaded<1)return "Load flares.";return "";}
 public bool ToggleUtility(int slot){if(InHubH&&slot>=0&&slot<16&&Player.Utilities[slot].Definition?.Kind is "CoreProbe" or "CombatProbe"){Say("Probes unavailable in restricted hub.");return false;}if(slot<0||slot>=16)return false;var s=Player.Utilities[slot];if(s.Active){s.StopRequested=true;if(s.Definition!.Harvest&&s.Definition.Family!="Gas"){FinishUtilityHarvest(s,Math.Clamp(1-s.CycleLeft/s.CycleDuration,0,1));StopUtility(s);}return true;}string error=UtilityActivationError(s);if(error.Length>0){Say(error);return false;}return StartUtilityCycle(s);}
 bool StartUtilityCycle(UtilityState s){var d=s.Definition!;float cap=d.Capacitor*Player.HarvestFactor(d,"cap")*(s.Payload?.Cap??1)*(d.Harvest?Player.SupportFactor("miningCap"):1);if(Player.Cap<cap){Say("Insufficient capacitor.");return false;}Player.Cap-=cap;s.Active=true;s.StopRequested=false;s.TargetId=LockedId;s.CycleDuration=Math.Max(.05f,d.Cycle*Player.HarvestFactor(d,"cycle")*Player.HullFactor("utility","cycle",d.Kind)*(d.Kind is "Survey" or "ShipScan" or "CargoScan"?Player.RigFactor("scannerCycle",false):1)*(d.Harvest?Player.SupportFactor("miningCycle"):1)*(s.Payload?.Cycle??1)*(d.Family=="Ice"?Player.UtilityFactor("iceCycle"):1));s.CycleLeft=s.CycleDuration;if(d.Analyzer){StartUtilityHack(s);s.Repeat=true;}if(d.Kind=="SurveyProbe"){s.Loaded--;s.CycleDuration=s.CycleLeft=300*Player.HullFactor("utility","cycle","SurveyProbe");}return true;}
 public void UpdateUtility(float dt){if(dt<=0)return;UpdateUtilityProbes(dt);if(IndustrialCore&&!ActiveSpecialCore){Player.Velocity=Vector3.Zero;CoreLeft-=dt;while(CoreLeft<=0&&IndustrialCore){if(CoreStop||ItemCount("ut_coolant",false)<30){IndustrialCore=false;CoreStop=false;CoreLeft=0;foreach(var s in Player.Utilities.Where(s=>s.Definition?.Kind=="Compress"))StopUtility(s);}else{ChangeStack("ut_coolant",false,-(decimal)(30));CoreLeft+=60;}}}
 foreach(var s in Player.Utilities){s.ReloadLeft=Math.Max(0,s.ReloadLeft-dt);if(!s.Active||s.Definition==null)continue;var d=s.Definition;var t=Targets.FirstOrDefault(t=>t.Id==s.TargetId&&t.Alive);if(d.Analyzer&&LockedId!=s.TargetId){FailUtilityHack();StopUtility(s);continue;}if(!s.Effective||d.Kind=="Compress"&&!IndustrialCore){StopUtility(s);continue;}if(d.Kind is not ("Compress" or "CoreProbe" or "CombatProbe")&&(t==null||d.Range>0&&Vector3.Distance(Player.Position,t.Position)>UtilityRange(d)+(d.Kind=="ShipScan"?d.Falloff:0))){if(d.Analyzer)FailUtilityHack();StopUtility(s);continue;}
 if(d.Kind=="Tractor"&&t!=null){var delta=Player.Position-t.Position;float move=Math.Min(Math.Max(0,delta.Length()-1500),d.TractorSpeed*Player.HullFactor("utility","speed","Tractor")*dt);if(delta.Length()>0)t.Position+=Vector3.Normalize(delta)*move;}
 s.CycleLeft-=dt;if(s.CycleLeft>0)continue;if(d.Harvest)FinishUtilityHarvest(s,1);else FinishUtilityCycle(s,t);if(d.Analyzer&&UtilityHackState is {Complete:false}){if(!StartUtilityCycleExistingHack(s))FailUtilityHack();continue;}bool repeat=s.Repeat&&!s.StopRequested&&d.Kind is not ("CoreProbe" or "CombatProbe" or "SurveyProbe")&&!d.Analyzer;StopUtility(s);if(repeat&&UtilityActivationError(s).Length==0)StartUtilityCycle(s);}
 }
 bool StartUtilityCycleExistingHack(UtilityState s){if(Player.Cap<s.Definition!.Capacitor){StopUtility(s);return false;}Player.Cap-=s.Definition.Capacitor;s.CycleLeft=s.CycleDuration;return true;}
 public void FinishUtilityTrialCycle(){if(!WeaponTestMode)return;var times=Player.Utilities.Where(s=>s.Active).Select(s=>s.CycleLeft).ToArray();if(times.Length>0)UpdateUtility(times.Max()+.001f);else if(ProbeScanLeft>0)UpdateUtility(ProbeScanLeft+.001f);}
 public void FinishUtilityHarvest(UtilityState s,float fraction){var d=s.Definition!;var t=Targets.FirstOrDefault(t=>t.Id==s.TargetId&&t.Alive);if(t==null)return;WeaponVisuals.Add(new(){Start=Player.Position,End=t.Position,Kind=WeaponKind.Turret,DamageType=DamageType.EM,Remaining=.7f});float yield=(d.Crystal&&s.Loaded>0&&s.Payload?.Resource==t.Resource?d.SpecialAmount*s.Payload.Yield:d.Amount)*(d.Family=="Ore"?Player.UtilityFactor("oreYield"):1)*(t.Resource=="deepore"?Player.RigFactor("deepOreYield"):1)*Player.HarvestFactor(d,"yield")*fraction;if(t.Id.StartsWith("q-rock:")){s.Harvested+=HarvestMiningQ(t,yield);return;}if(t.Id.StartsWith("f:")&&t.Id.Contains(":ore:")){s.Harvested+=HarvestEncounterF(t,yield);return;}if(t.Id.StartsWith("mission:")){float collected=HarvestMission38(t,yield);s.Harvested+=collected;Say($"Contract harvest: {collected:0} m3.");return;}float unit=ItemVolume(t.Resource);float qty=MathF.Floor(Math.Min(Math.Min(yield,t.Ore),CargoRoom(t.Resource))/unit);float baseVolume=qty*unit;if(qty<=0)return;t.Ore=Math.Max(0,t.Ore-baseVolume);float criticalChance=d.CritChance*(d.Family is "Ore" or "Ice"?Player.UtilityFactor("critChance"):1);if(RollProductionE()<criticalChance){float extra=MathF.Floor(Math.Min(baseVolume*d.CritYield*Player.UtilityFactor("critYield"),CargoRoom(t.Resource)-baseVolume)/unit);qty+=Math.Max(0,extra);s.Criticals++;}
 float chance=Math.Clamp((d.ResidueChance+(s.Payload?.WasteChance??0))*Player.UtilityFactor("residueChance"),0,1);if(RollProductionE()<chance){float waste=Math.Min(t.Ore,baseVolume*(d.ResidueVolume+(s.Payload?.WasteVolume??0)));t.Ore-=waste;s.Residue+=waste;}ChangeStack(t.Resource,false,(decimal)(qty));s.Harvested+=qty*unit;if(t.Id=="rock")_oreRemaining[SystemId]=t.Ore;if(s.Payload?.Kind=="Crystal"&&s.Loaded>0&&RollProductionE()<s.Payload.WearChance*Player.SupportFactor("crystalWear")){s.CrystalWear+=s.Payload.WearDamage;if(s.CrystalWear>=1){s.Loaded=0;s.CrystalWear=0;Say("Mining prism fractured.");}}if(t.Resource=="deepore"&&RollProductionE()<d.CloudChance){Player.Shield=Math.Max(0,Player.Shield-80);Say("Deep-core gas release: shields damaged.");}Say($"{d.Name}: {qty:0} {t.Resource}; total residue {s.Residue:0} m3.");}
 void FinishUtilityCycle(UtilityState s,SpaceTarget? t){var d=s.Definition!;if(d.Kind is "CoreProbe" or "CombatProbe"){DeployUtilityProbes(s);return;}if(t==null)return;if(d.Kind=="SurveyProbe"){UtilityReports.Insert(0,"Lunar assay: "+t.Name+" / Lunarite 62%, Riftstone 24%, Vesperite 14%.");return;}
 if(d.Kind=="CargoScan"&&t.Profile?.HullCapability("immune to all cargo scanners")==true){UtilityReports.Insert(0,t.Name+" / cargo scan blocked by hull shielding.");return;}
 if(d.Kind=="CargoScan")ScannedP(t);if(d.Kind=="CargoScan")UtilityReports.Insert(0,t.Name+" cargo: "+(t.Contents.Count==0?"Empty":string.Join(", ",t.Contents.Select(x=>x.Key+" "+x.Value))));
 if(d.Kind=="ShipScan"){float dist=Vector3.Distance(Player.Position,t.Position);float chance=dist<=d.Range?1:MathF.Pow(.5f,(dist-d.Range)/Math.Max(1,d.Falloff));var ship=t.Profile;var fitting=ship==null?[]:ship.Weapons.Select(s=>s.ModuleId).Concat(ship.Ewar.Select(s=>s.ModuleId)).Concat(ship.Defense.Select(s=>s.ModuleId)).Concat(ship.Support.Select(s=>s.ModuleId)).Concat(ship.Utilities.Select(s=>s.ModuleId)).Concat(ship.Enhancements.Select(s=>s.ModuleId)).Concat(ship.Mobility.Select(s=>s.ModuleId)).Where(id=>id.Length>0&&_rng.NextDouble()<chance*.8).ToArray();UtilityReports.Insert(0,t.Name+$" capacitor {t.Cap:0} GJ / observed fitting: "+string.Join(", ",fitting));}
 if(d.Kind=="Salvage"){float chance=Math.Clamp(.15f+d.SalvageChance+Player.RigAdd("salvageChanceAdd")-t.SalvageDifficulty,0,1);if(_rng.NextDouble()<chance){float q=Math.Min(t.Salvage,MathF.Floor((Player.CargoMax-CargoUsed)/ItemVolume("salvage")));if(q>0){t.Salvage-=q;SalvagedP(t,q);ChangeStack("salvage",false,(decimal)(q));Say("Recovered "+q+" components.");}}else Say("Salvage attempt failed; wreck retained.");}
 if(d.Kind=="Festival"){s.Loaded--;WeaponVisuals.Add(new(){Start=Player.Position,End=t.Position,Kind=WeaponKind.Bomb,Radius=250,Remaining=1.4f,DamageType=DamageType.EM});UtilityReports.Insert(0,"Prismatic flare discharged at "+t.Name+"; no combat damage.");}while(UtilityReports.Count>30)UtilityReports.RemoveAt(UtilityReports.Count-1);}
 public bool ToggleIndustrialCore(){int fitted=Array.FindIndex(Player.Special,s=>s.Definition?.Kind=="Core");if(fitted>=0)return ToggleSpecial(fitted);if(!WeaponTestMode){Say("Fit a size-compatible industrial core first.");return false;}if(IndustrialCore){CoreStop=true;return true;}if(Docked||Player.MobilitySpooling||CombatHulls.Get(Player.CombatHull).Role is not ("MiningTender" or "ExpeditionCommand" or "CapitalIndustrial")||ItemCount("ut_coolant",false)<30)return false;ChangeStack("ut_coolant",false,-(decimal)(30));IndustrialCore=true;CoreStop=false;CoreLeft=60;Player.Velocity=Vector3.Zero;Player.Order="stop";return true;}
 public bool CompressUtility(string resource,int quantity){if(quantity<=0||!IndustrialCore||ItemCount(resource,false)<quantity)return false;string family=resource switch{"ore"=>"Asteroid Ore","deepore"=>"Deep Ore","moonore"=>"Moon Ore","gas"=>"Gas","ice"=>"Ice",_=>""};if(family==""||!Player.Utilities.Any(s=>s.Active&&s.Effective&&s.Definition?.Kind=="Compress"&&s.Definition.Family==family))return false;ChangeStack(resource,false,-(decimal)(quantity));ChangeStack("compressed_"+resource,false,(decimal)(quantity));return true;}
 public bool DecompressUtility(string resource,int quantity){string id="compressed_"+resource;if(!Docked||quantity<=0||!UtilityItems.All.Any(i=>i.Id==id)||ItemCount(id,true)<quantity)return false;ChangeStack(id,true,-(decimal)(quantity));ChangeStack(resource,true,(decimal)(quantity));return true;}
 public bool LootUtilityTarget(string itemFilter=""){if(SelectedId.StartsWith("wreck-d:"))return LootWreckD(SelectedId,itemFilter);var t=Selected;if(t==null||!t.Alive||ProtectedP(t)||t.Kind is not (TargetKind.Container or TargetKind.Wreck)||Vector3.Distance(Player.Position,t.Position)>2500||t.SiteKind is "Data" or "Relic"&&!t.Hacked)return false;if(!t.Contents.Any(i=>i.Value>0&&(itemFilter.Length==0||i.Key==itemFilter)&&CargoRoom(i.Key)>=ItemVolume(i.Key))||!LegalTheftQ(t.OwnerId))return false;bool any=false;foreach(var x in t.Contents.Where(x=>itemFilter.Length==0||x.Key==itemFilter).ToArray()){float q=Math.Min(x.Value,MathF.Floor(CargoRoom(x.Key)/ItemVolume(x.Key)));if(q<=0)continue;any=true;ChangeStack(x.Key,false,(decimal)(q));t.Contents[x.Key]-=q;}if(ActiveEncounterF is {} e)EvaluateEncounterF(e);SyncEncounterF();return any;}
